mapper.select:
SELECT COALESCE(MAX(research_round), 0)
FROM assistant_agent_collection_plan
WHERE agent_task_id = #{agentTaskId}

mapper.update:
UPDATE assistant_agent_collection_plan
SET status = #{targetStatus}, version = version + 1, update_time = #{updateTime},
    confirm_time = CASE WHEN #{targetStatus} = 'CONFIRMED' THEN #{updateTime} ELSE confirm_time END
WHERE id = #{id}
  AND status = #{expectedStatus}
  AND version = #{expectedVersion}
